import unittest
import copy, json, sys
sys.path.insert(0, '.')
from utility.water import litre_rate

def run_case(a):
    return litre_rate(*a)

def _norm(x):
    return json.loads(json.dumps(x))

def _outcome(case):
    try:
        return _norm(run_case(copy.deepcopy(case)))
    except Exception as e:
        return {"raises": type(e).__name__}

CASES = json.loads("[[11611], [55221], [55222], [11612], [9772], [0], [9771], [9770], [60000], [120000], [0], [34735], [-1], [49669], [34734], [49667], [34736], [11610], [49668], [55223]]")
WANT = json.loads("[187, 447, 447, 322, 187, 149, 149, 149, 485, 485, 149, 322, {\"raises\": \"ValueError\"}, 447, 322, 443, 443, 187, 443, 485]")


class RecordedTests(unittest.TestCase):
    def test_recorded_outcomes(self):
        for i, case in enumerate(CASES):
            with self.subTest(i=i, case=str(case)[:200]):
                self.assertEqual(_outcome(case), WANT[i])


if __name__ == '__main__':
    unittest.main()

hidden.tests/test_zz_structure.py:
import ast
import unittest

import structlib as S

BOUND = 3
ENTRY_PATH = "utility/water.py"
ENTRY_FUNCTIONS = ["litre_rate"]


class StructureTests(unittest.TestCase):
    def test_entry_points_remain(self):
        names = {n.name for n in S.parse(ENTRY_PATH).body if isinstance(n, ast.FunctionDef)}
        self.assertFalse(set(ENTRY_FUNCTIONS) - names)

    def test_no_conditional_ladders(self):
        bad = []
        for rel in S.py_files("."):
            src = S.read(rel)
            for q, fn in S.functions(ast.parse(src)):
                n = S.branch_nodes(fn)
                if n > BOUND:
                    bad.append("%s:%s has %d conditional branches (limit %d)" % (rel, q, n, BOUND))
        self.assertFalse(bad, "ladders remain:\n" + S.format_problems(bad))

