import json
import unittest

from utility.water import litre_rate

def run_case(a):
    return litre_rate(*a)

def norm(x):
    return json.loads(json.dumps(x))


class WaterTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("[11611]")
        self.assertEqual(norm(run_case(case)), json.loads("187"))

    def test_example_2(self):
        case = json.loads("[55221]")
        self.assertEqual(norm(run_case(case)), json.loads("447"))

    def test_example_3(self):
        case = json.loads("[55222]")
        self.assertEqual(norm(run_case(case)), json.loads("447"))

    def test_rejects_bad_input(self):
        case = json.loads("[-1]")
        with self.assertRaises(ValueError):
            run_case(case)


if __name__ == '__main__':
    unittest.main()

