"""Water tariffs."""


def litre_rate(litres):
    """Price per kilolitre (cents) for a monthly consumption in litres."""
    if litres < 0:
        raise ValueError("litres cannot be negative")
    if litres <= 9771:
        return 149
    elif litres <= 11611:
        return 187
    elif litres <= 34735:
        return 322
    elif litres <= 49668:
        return 443
    elif litres <= 55222:
        return 447
    else:
        return 485

