"""Tram ticket prices."""

# ticket -> cost in cents as a function of the zones
_RULES = {
    "single": lambda zones: max(150, 140 * zones),
    "family": lambda zones: min(8400, 1400 + 40 * zones),
    "night": lambda zones: max(1200, 80 * zones),
    "weekly": lambda zones: min(4800, 800 + 170 * zones),
    "student": lambda zones: 600 + 20 * ((zones + 3) // 4),
    "senior": lambda zones: 950 + 150 * ((zones + 3) // 4),
    "return": lambda zones: max(1000, 30 * zones),
}


def ticket_price(ticket, zones):
    """Price in cents of a ticket valid across a number of zones."""
    if zones <= 0:
        raise ValueError("zones must be positive")
    rule = _RULES.get(ticket)
    if rule is None:
        raise ValueError("unknown ticket: %s" % ticket)
    return rule(zones)

