"""Library late fines."""

# item_type -> cost in cents as a function of the days
_RULES = {
    "reader": lambda days: max(900, 70 * days),
    "laptop": lambda days: 1300 + 40 * ((days + 2) // 3),
    "boardgame": lambda days: 750 + 90 * days,
    "tool": lambda days: 1250 + 190 * days,
    "dvd": lambda days: max(250, 20 * days),
    "magazine": lambda days: 400 + 130 * ((days + 2) // 3),
}


def late_fine(item_type, days):
    """Fine in cents for an item that is some days late."""
    if days <= 0:
        raise ValueError("days must be positive")
    rule = _RULES.get(item_type)
    if rule is None:
        raise ValueError("no fine schedule for %s" % item_type)
    return rule(days)

