"""Library late fines."""


def late_fine(item_type, days):
    """Fine in cents for an item that is some days late."""
    if days <= 0:
        raise ValueError("days must be positive")
    if item_type == "reader":
        cost = max(900, 70 * days)
    elif item_type == "laptop":
        cost = 1300 + 40 * ((days + 2) // 3)
    elif item_type == "boardgame":
        cost = 750 + 90 * days
    elif item_type == "tool":
        cost = 1250 + 190 * days
    elif item_type == "dvd":
        cost = max(250, 20 * days)
    elif item_type == "magazine":
        cost = 400 + 130 * ((days + 2) // 3)
    else:
        raise ValueError("no fine schedule for %s" % item_type)
    return cost

