        self.assertFalse(set(ENTRY_FUNCTIONS) - names)

    def test_no_conditional_ladders(self):
        bad = []
        for rel in S.py_files("."):
            src = S.read(rel)
            for q, fn in S.functions(ast.parse(src)):
                n = S.branch_nodes(fn)
                if n > BOUND:
                    bad.append("%s:%s has %d conditional branches (limit %d)" % (rel, q, n, BOUND))
