"""Drone delivery tracking."""


def apply_update(state, event):
    """Apply a tracking update to a parcel record and return the notifications to send."""
    kind = event["kind"]
    actions = []
    if kind == "failed":
        state["attempts"] += 1
        if state["attempts"] >= 4:
            state["status"] = "returning"
            actions.append("return to sender")
        else:
            state["status"] = "retry"
            actions.append("schedule attempt %d" % (state["attempts"] + 1))
    elif kind == "lost":
        state["status"] = "lost"
        actions.append("open insurance claim")
        if event.get("value", 0) > 400:
            actions.append("assign adjuster")
    elif kind == "delayed":
        minutes = event.get("minutes", 0)
        if minutes > 50:
            state["status"] = "late"
            actions.append("apologise and offer credit")
        else:
            actions.append("send new eta")
    elif kind == "picked_up":
        state["status"] = "in_flight"
        actions.append("notify sender: picked up")
        if event.get("battery", 100) < 30:
            actions.append("swap battery at next hub")
    elif kind == "delivered":
        state["status"] = "delivered"
        actions.append("send photo proof")
        if event.get("signed"):
            actions.append("close ticket")
    elif kind == "returned":
        state["status"] = "returned"
        actions.append("refund shipping")
        if state["attempts"] == 0:
            actions.append("flag address error")
    elif kind == "rescheduled":
        day = event.get("day", 0)
        if day > 9:
            actions.append("reject: too far out")
        else:
            state["status"] = "scheduled"
            actions.append("confirm day %d" % day)
    else:
        raise ValueError("unknown tracking update: %s" % kind)
    state["last"] = event["kind"]
    return actions

