class TrackingTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("[{\"status\": \"in_flight\", \"attempts\": 3, \"history\": []}, {\"kind\": \"delayed\", \"battery\": 79, \"minutes\": 112, \"day\": 1, \"signed\": true, \"value\": 632}]")
        self.assertEqual(norm(run_case(case)), json.loads("{\"actions\": [\"apologise and offer credit\"], \"state\": {\"status\": \"late\", \"attempts\": 3, \"history\": [], \"last\": \"delayed\"}}"))

    def test_example_2(self):
        case = json.loads("[{\"status\": \"retry\", \"attempts\": 2, \"history\": []}, {\"kind\": \"failed\", \"battery\": 28, \"minutes\": 65, \"day\": 2, \"signed\": true, \"value\": 608}]")
        self.assertEqual(norm(run_case(case)), json.loads("{\"actions\": [\"schedule attempt 4\"], \"state\": {\"status\": \"retry\", \"attempts\": 3, \"history\": [], \"last\": \"failed\"}}"))

    def test_example_3(self):
        case = json.loads("[{\"status\": \"created\", \"attempts\": 3, \"history\": []}, {\"kind\": \"returned\", \"battery\": 53, \"minutes\": 113, \"day\": 3, \"signed\": true, \"value\": 279}]")
        self.assertEqual(norm(run_case(case)), json.loads("{\"actions\": [\"refund shipping\"], \"state\": {\"status\": \"returned\", \"attempts\": 3, \"history\": [], \"last\": \"returned\"}}"))

