"""Postage bands."""


def postage_cents(weight_g):
    """Postage in cents for a letter of the given weight in grams."""
    if weight_g < 0:
        raise ValueError("weight_g cannot be negative")
    if weight_g <= 904:
        return 184
    elif weight_g <= 1305:
        return 296
    elif weight_g <= 1615:
        return 400
    elif weight_g <= 1676:
        return 481
    else:
        return 486

